WFJ.Data.add("book", {
  ["5732991b8c3df657"] = { "Speravo di dimostrare ai miei colleghi che questo tipo di pietra possedeva davvero proprietà magiche e che, se noi maghi di Dalaran non volevamo sfruttare il potere delle sanguiniti, avremmo dovuto almeno conoscerne le proprietà, perché un giorno i nostri nemici potrebbero usarle contro di noi.\n\nE così cominciarono i miei studi.", "." },
  ["573fe1907aa660eb"] = { "Magistrato Rutherford Burnside\nTutti i debiti saldati.\n\nFabbro Avery Verringtan\nTutti i debiti saldati.\n\nScrivano Horrace Whitesteed\nTutti i debiti saldati.\n\nConsigliere Gillis\nTutti i debiti saldati.\n\nConsigliere Hooks\nTutti i debiti saldati.\n\nContadino Getz\nTutti i debiti saldati.\n\n⟦Farmer Ray=Contadino Ray⟧\nDebito insoluto. Pagamento in prodotti agricoli promesso al momento del raccolto.\n\nContadino Lyion\nDebito insoluto. Sfrattato dalla terra.", "." },
  ["574acbe4060c3366"] = { "Liferoot:\n\nSi può raccogliere in natura oppure ottenere dalle bestie Withervine di ⟦Dustwallow Marsh=Acquemorte⟧. Il suo potere sarà necessario per attirare in questo mondo l'essenza vitale di Ciclonian.", "." },
  ["577c499d640b29e2"] = { "Temo che un male più grande e più oscuro stia ribollendo nel calderone di corruzione in cui si sono trasformate le terre del nord. È indispensabile che il Regno di ⟦Stormwind=Roccavento⟧ agisca, se non vogliamo diventare ricordi sbiaditi per i vivi o schiavi del nemico.\n\nIn fede,\n\nMagistrato Solomon\nMunicipalità di ⟦Lakeshire=Borgolago⟧\nRegno di ⟦Stormwind=Roccavento⟧", "." },
  ["578080fa884afad7"] = { "Zimrel Darktooth\n\nQuando la follia della chiave oscura si impadronisce di Zimrel, solo le urla dei moribondi riescono a placarlo.\n\nPer il suo sacrificio, avrà sempre un posto sulle panche sopra l'arena. Che i nostri giochi di sangue temperino la furia nel suo cuore.", "." },
  ["57c6f7777ac11b50"] = { "Questo è lo scopo del mio libro: catalogare quegli esseri, quelle creature immonde venute da altri mondi che vorrebbero distruggere le nostre terre, così che gli esploratori che dovessero imbattersi in loro sappiano che cosa affrontano.\n\nPerciò, se ti consideri tra i guardiani di Azeroth, continua a leggere. E conosci il tuo nemico.\n\n-Ur\nMago di Dalaran", "." },
  ["57e6ea9e04690abd"] = { "VanCleef...<testo illeggibile>\n\nRICHIAMARE me?? CHI SI CREDE DI ESSERE?? Io sono Klaven Mortwake! Non prendo ordini da un insetto!\n\n<il resto delle pagine del libro manca>", "." },
